parameters.jsCode:
// NORMALIZACIÓN TRIBUTARIA DIAN / FACTURATECH
const body = $input.item.json.body || $input.item.json;

// 1. Extraer datos del cliente
const rawName = (body.customerName || body.clientName || body.name || "Cliente Final").trim();
const rawEmail = (body.customerEmail || body.email || "facturacion@videm.tv").trim().toLowerCase();
const rawCountry = (body.country || body.pais || "ES").toUpperCase().trim();
const rawDoc = (body.documentId || body.dni || body.cedula || "").trim();
const rawPhone = (body.phone || body.whatsapp || "").trim();

// 2. Extraer datos de la compra
const rawPlan = (body.plan || body.planName || "6 Meses VIP").toLowerCase();
const isSpain = rawCountry === "ES" || rawCountry === "ESPAÑA" || rawCountry === "ESP";

let planCode = "";
let planTitle = "";
let unitPrice = 0;
let currency = "";
let taxRate = 0;
let taxExemptionNote = "";
let docType = "";
let docNumber = "";

// Configuración específica de cada país
if (isSpain) {
  currency = "EUR";
  docType = "42"; // Documento de identificación extranjero (DNI / NIE)
  docNumber = rawDoc || ("CLI-" + Math.floor(100000 + Math.random() * 900000));
  taxRate = 0; // Exento de IVA
  taxExemptionNote = "Exportación de servicios exenta de IVA - Art. 481 literal c del Estatuto Tributario.";

  if (rawPlan.includes("12") || rawPlan.includes("anual")) {
    planCode = "VIDEM-VIP-12";
    planTitle = "Suscripción Servicio Streaming Concierge (12 Meses)";
    unitPrice = 89.99;
  } else if (rawPlan.includes("1") || rawPlan.includes("flex") || rawPlan.includes("mes")) {
    planCode = "VIDEM-FLEX-01";
    planTitle = "Servicio Streaming Concierge VIP (1 Mes)";
    unitPrice = 9.99;
  } else {
    // Plan Estrella por defecto
    planCode = "VIDEM-VIP-06";
    planTitle = "Suscripción Servicio Streaming Concierge (6 Meses)";
    unitPrice = 49.99;
  }
} else {
  // Colombia
  currency = "COP";
  docType = rawDoc ? "13" : "13"; // Cédula de ciudadanía
  docNumber = rawDoc || "222222222222"; // Consumidor Final DIAN estándar
  taxRate = 0; // Régimen No Responsable (LevannaDC)
  taxExemptionNote = "Operación efectuada por persona natural no responsable de IVA.";

  if (rawPlan.includes("12") || rawPlan.includes("anual")) {
    planCode = "VIDEM-CO-12";
    planTitle = "Asistencia Streaming Concierge Anual (12 Meses)";
    unitPrice = 440000;
  } else if (rawPlan.includes("1") || rawPlan.includes("flex")) {
    planCode = "VIDEM-CO-01";
    planTitle = "Asistencia Streaming Concierge (1 Mes)";
    unitPrice = 55000;
  } else {
    planCode = "VIDEM-CO-06";
    planTitle = "Asistencia Streaming Concierge VIP (6 Meses)";
    unitPrice = 240000;
  }
}

// Payload estructurado para Facturatech
const facturatechPayload = {
  tipoDocumento: "01", // Factura Electrónica de Venta
  tipoOperacion: isSpain ? "02" : "10", // 02: Exportación | 10: Venta Estándar
  divisa: currency,
  cliente: {
    nombre: rawName,
    email: rawEmail,
    pais: isSpain ? "ES" : "CO",
    tipoDocumento: docType,
    numeroDocumento: docNumber,
    telefono: rawPhone,
    responsabilidadFiscal: "R-99-PN" // No responsable / Persona Natural
  },
  items: [
    {
      esquema: "010", // Estándar de adopción del contribuyente
      codigo: planCode,
      nombre: planTitle,
      unidadMedida: "94", // Servicio / Unidad (evita decimales)
      cantidad: 1,
      precioUnitario: unitPrice,
      impuestoIva: taxRate,
      notaLegal: taxExemptionNote
    }
  ],
  metadata: {
    origenPago: body.gateway || "Stripe/MercadoPago",
    referenciaPago: body.paymentId || body.reference || ("TX-" + Date.now())
  }
};

// Texto formateado para el mensaje con botones al administrador
const approvalMessage = [
  "🧾 *VIDEM BILLING | NUEVA VENTA DETECTADA*",
  "",
  "👤 *Cliente:* " + rawName,
  "📧 *Email:* " + rawEmail,
  "🌍 *Destino:* " + (isSpain ? "🇪🇸 España (Exportación de Servicio - IVA 0%)" : "🇨🇴 Colombia (Nacional)"),
  "🆔 *Documento:* " + docNumber + " (Tipo " + docType + ")",
  "📦 *Plan:* " + planTitle,
  "💰 *Monto a Facturar:* " + unitPrice + " " + currency,
  "🔢 *Ref Pago:* " + facturatechPayload.metadata.referenciaPago,
  "",
  "¿Deseas autorizar la transmisión electrónica a la DIAN a través de Facturatech?"
].join("\n");

return {
  facturatechPayload,
  approvalMessage,
  clientEmail: rawEmail,
  clientName: rawName,
  unitPrice,
  currency,
  isSpain
};

